diff --git a/src/queue.js b/src/queue.js
index 66cc5fe..e29bebe 100644
--- a/src/queue.js
+++ b/src/queue.js
@@ -3,23 +3,43 @@ export class AsyncQueue {
     this.concurrency = concurrency;
     this.maxSize = maxSize;
     this.running = 0;
-    this.queue = [];
+    // Tasks awaiting a free slot, in FIFO order. Each entry retains the
+    // caller's resolve/reject so its promise settles when the task runs.
+    this.pending = [];
+    // Guards against re-entrant drains while a slot is being admitted.
+    this.draining = false;
   }
-  async push(fn) {
-    if (this.running >= this.concurrency) {
-      if (this.queue.length >= this.maxSize) {
-        throw new Error('Queue full');
-      }
-      this.queue.push(fn);
-      return;
-    }
-    this.running++;
-    try { await fn(); } finally {
-      this.running--;
-      if (this.queue.length > 0) {
-        const next = this.queue.shift();
-        this.push(next);
+
+  push(fn) {
+    return new Promise((resolve, reject) => {
+      this.pending.push({ fn, resolve, reject });
+      this.drain();
+    });
+  }
+
+  // Single admission path shared by enqueue and completion: admit as many
+  // pending tasks as concurrency allows, never rejecting when saturated.
+  drain() {
+    if (this.draining) return;
+    this.draining = true;
+    try {
+      while (this.running < this.concurrency && this.pending.length > 0) {
+        const task = this.pending.shift();
+        this.running++;
+        this.run(task);
       }
+    } finally {
+      this.draining = false;
     }
   }
+
+  run(task) {
+    Promise.resolve()
+      .then(() => task.fn())
+      .then(task.resolve, task.reject)
+      .finally(() => {
+        this.running--;
+        this.drain();
+      });
+  }
 }
